#include "inc/registry.hpp"

int registry::operator[]
    (std::string_view id) const
{
    for (size_t i = 0; i < entries().data.size(); ++i)
        if (id == entries().data[i].id().value)
            return i;

    throw std::out_of_range("bad id");
}

std::string_view registry::operator[]
    (int id) const
{
    if (id >= (int) entries().data.size())
        throw std::out_of_range("bad id");

    return entries().data[id].id().value;
}

void registry_manager::queue_synced_registries_packets(
    std::function<void(const packet_registry_data &)> callback
){
    callback((*this)["minecraft:banner_pattern"]);
    callback((*this)["minecraft:damage_type"]);
    callback((*this)["minecraft:dimension_type"]);
    callback((*this)["minecraft:instrument"]);
    callback((*this)["minecraft:jukebox_song"]);
    callback((*this)["minecraft:painting_variant"]);
    callback((*this)["minecraft:sulfur_cube_archetype"]);
    callback((*this)["minecraft:timeline"]);
    callback((*this)["minecraft:trim_material"]);
    callback((*this)["minecraft:world_clock"]);
    callback((*this)["minecraft:worldgen/biome"]);
    callback((*this)["minecraft:cat_variant"]);
    callback((*this)["minecraft:cat_sound_variant"]);
    callback((*this)["minecraft:chicken_variant"]);
    callback((*this)["minecraft:chicken_sound_variant"]);
    callback((*this)["minecraft:cow_variant"]);
    callback((*this)["minecraft:cow_sound_variant"]);
    callback((*this)["minecraft:frog_variant"]);
    callback((*this)["minecraft:pig_variant"]);
    callback((*this)["minecraft:pig_sound_variant"]);
    callback((*this)["minecraft:wolf_variant"]);
    callback((*this)["minecraft:wolf_sound_variant"]);
    callback((*this)["minecraft:zombie_nautilus_variant"]);
}

